254	
255	      <MetaField
256	        icon={
257	          <ArrowRight className="h-4 w-4 text-primary" aria-hidden="true" />
258	        }
259	        label="Next Action"
260	      >
261	        {nextAction ? (
262	          <span className="text-text-primary">{nextAction}</span>
