281	        </div>
282	      </MetaField>
283	
284	      <MetaField label="Depends On" fullWidth>
285	        {task.dependsOn.length > 0 ? (
286	          <div className="flex flex-wrap gap-1.5">
287	            {task.dependsOn.map((dep) => (
288	              <span
289	                key={dep}
290	                className="bg-chip-bg px-2 py-0.5 text-xs font-medium text-text-secondary"
291	              >
292	                {dep}
293	              </span>
