387	function PullRequestCard({
388	  label,
389	  url,
390	  icon,
391	}: {
392	  label: string;
393	  url: string | undefined;
394	  icon: React.ReactNode;
395	}) {
396	  if (!url) {
397	    return (
398	      <div
399	        aria-disabled="true"
400	        className="pointer-events-none flex items-center justify-between border border-border bg-surface px-3 py-2.5 opacity-70"
401	      >
402	        <div className="flex items-center gap-2">
403	          <span className="text-text-muted">{icon}</span>
404	          <span className="text-sm font-medium text-text-secondary">
405	            {label}
406	          </span>
407	        </div>
408	        <span className="italic text-xs text-text-muted">None</span>
409	      </div>
410	    );
411	  }
412	
413	  return (
414	    <a
415	      href={url}
416	      target="_blank"
417	      rel="noreferrer noopener"
418	      className="flex items-center justify-between border border-border bg-surface px-3 py-2.5 transition-colors hover:border-primary-light hover:bg-surface-subtle"
419	    >
420	      <div className="flex items-center gap-2">
421	        <span className="text-text-secondary">{icon}</span>
422	        <span className="text-sm font-medium text-text-primary">{label}</span>
423	      </div>
424	      <div className="flex items-center gap-2">
425	        <ExternalLink
426	          className="h-3.5 w-3.5 text-text-muted"
427	          aria-hidden="true"
428	        />
429	      </div>
430	    </a>
431	  );
432	}
433	
434	function TimelineSection({ log }: { log: LogEntry[] | undefined }) {
435	  const timelineEntries = getSortedTimelineEntries(log);
436	
437	  return (
438	    <section className="mt-6 border-t border-border pt-5">
439	      <h3 className="mb-3 text-sm font-semibold text-text-primary">
440	        Activity Timeline
441	      </h3>
442	      {timelineEntries.length > 0 ? (
443	        <ol className="flex flex-col gap-3">
444	          {timelineEntries.map((entry, index) => (
445	            <TimelineEntry
446	              key={`${entry.at}-${index}`}
447	              entry={entry}
448	              isLast={index === timelineEntries.length - 1}
449	            />
450	          ))}
451	        </ol>
452	      ) : (
453	        <p className="text-sm text-text-muted">No activity logs available.</p>
454	      )}
455	    </section>
456	  );
457	}
458	
459	function getSortedTimelineEntries(log: LogEntry[] | undefined): LogEntry[] {
460	  if (!log || log.length === 0) return [];
461	
462	  return log
463	    .map((entry, sequence) => {
464	      const time = new Date(entry.at).getTime();
465	      return {
466	        entry,
467	        sequence,
468	        sortTime: Number.isNaN(time) ? Number.NEGATIVE_INFINITY : time,
469	      };
470	    })
471	    .sort((a, b) => {
472	      if (a.sortTime !== b.sortTime) return b.sortTime - a.sortTime;
473	      return a.sequence - b.sequence;
474	    })
475	    .map(({ entry }) => entry);
476	}
477	
478	function getTimelineStatusKey(action: string): string {
479	  if (action === "started" || action === "claimed") return "in_progress";
480	  if (action === "moved_to_review") return "in_review";
481	  return action;
482	}
483	
484	function TimelineEntry({
485	  entry,
486	  isLast,
487	}: {
488	  entry: LogEntry;
489	  isLast: boolean;
490	}) {
491	  const statusStyle = getStatusStyle(getTimelineStatusKey(entry.action));
492	
493	  return (
494	    <li data-task-timeline-entry className="flex gap-3">
495	      <div className="flex flex-col items-center pt-1">
496	        <span
497	          className={"h-2 w-2 rounded-full " + statusStyle.dot}
498	          aria-hidden="true"
499	        />
500	        {isLast ? null : (
501	          <span className="mt-1 w-px flex-1 bg-border" aria-hidden="true" />
502	        )}
503	      </div>
504	      <div className="flex flex-1 flex-col gap-0.5 pb-3">
505	        <div className="flex items-center justify-between gap-2">
506	          <TimelineStatusBadge
507	            action={entry.action}
508	            statusStyle={statusStyle}
509	          />
510	          <span className="text-xs text-text-muted">
511	            {formatTimestamp(entry.at)}
512	          </span>
513	        </div>
514	        <span className="text-xs text-text-muted">by {entry.by}</span>
515	        {entry.note ? (
516	          <p className="mt-1 text-sm text-text-secondary">{entry.note}</p>
517	        ) : null}
518	      </div>
519	    </li>
520	  );
521	}
522	
523	function TimelineStatusBadge({
524	  action,
525	  statusStyle,
526	}: {
527	  action: string;
528	  statusStyle: StatusBadgeStyle;
529	}) {
530	  return (
531	    <span
532	      data-task-timeline-status={action}
533	      className={
534	        "border border-border px-2 py-0.5 text-xs font-semibold uppercase tracking-wide " +
535	        statusStyle.bg +
536	        " " +
537	        statusStyle.text
538	      }
539	    >
540	      {formatStatusLabel(action)}
541	    </span>
542	  );
543	}
