"use client";

import { useEffect, useId } from "react";
import {
  AlertCircle,
  ArrowRight,
  Bot,
  ExternalLink,
  GitBranch,
  GitPullRequest,
  Layers,
  User,
  X,
} from "lucide-react";
import type { LogEntry, ParsedTask } from "@/services/yaml-parser";
import { formatTimestamp } from "@/lib/time";
import {
  formatStatusLabel,
  getStatusStyle,
  type StatusBadgeStyle,
} from "../../lib/status";

export type TaskDetailSheetProps = {
  task: ParsedTask | null;
  featureTitle?: string;
  repository?: string;
  nextAction?: string;
  onClose: () => void;
};

export function TaskDetailSheet({
  task,
  featureTitle,
  repository,
  nextAction,
  onClose,
}: TaskDetailSheetProps) {
  const open = task !== null;
  const titleId = useId();
  const descId = useId();

  useEffect(() => {
    if (!open) return;
    const handleKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
    };
    document.addEventListener("keydown", handleKey);
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      document.removeEventListener("keydown", handleKey);
      document.body.style.overflow = previousOverflow;
    };
  }, [open, onClose]);

  return (
    <div
      aria-hidden={!open}
      className={
        "fixed inset-0 z-40 " +
        (open ? "pointer-events-auto" : "pointer-events-none")
      }
    >
      <button
        type="button"
        aria-label="Close task detail"
        tabIndex={open ? 0 : -1}
        onClick={onClose}
        className={
          "absolute inset-0 cursor-default bg-black/80 transition-opacity duration-200 " +
          (open ? "opacity-100" : "opacity-0")
        }
      />
      <aside
        role="dialog"
        aria-modal="true"
        aria-labelledby={titleId}
        aria-describedby={descId}
        className={
          "absolute right-0 top-0 flex h-full w-full flex-col bg-surface shadow-xl transition-transform duration-200 ease-out " +
          "sm:max-w-md md:max-w-lg lg:max-w-xl " +
          (open ? "translate-x-0" : "translate-x-full")
        }
      >
        {task ? (
          <TaskDetailContents
            task={task}
            featureTitle={featureTitle}
            repository={repository}
            nextAction={nextAction}
            onClose={onClose}
            titleId={titleId}
            descId={descId}
          />
        ) : null}
      </aside>
    </div>
  );
}

type ContentsProps = {
  task: ParsedTask;
  featureTitle: string | undefined;
  repository: string | undefined;
  nextAction: string | undefined;
  onClose: () => void;
  titleId: string;
  descId: string;
};

function TaskDetailContents({
  task,
  featureTitle,
  repository,
  nextAction,
  onClose,
  titleId,
  descId,
}: ContentsProps) {
  const statusStyle = getStatusStyle(task.status);
  const lastUpdatedAt = task.execution?.last_updated_at;

  return (
    <>
      <DetailHeader
        task={task}
        featureTitle={featureTitle}
        statusStyle={statusStyle}
        onClose={onClose}
        titleId={titleId}
        descId={descId}
      />
      <div className="flex-1 overflow-y-auto px-6 py-5">
        <MetadataSection
          task={task}
          repository={repository}
          nextAction={nextAction}
          lastUpdatedAt={lastUpdatedAt}
        />
        <PullRequestsSection task={task} />
        <TimelineSection log={task.log} />
      </div>
    </>
  );
}

function DetailHeader({
  task,
  featureTitle,
  statusStyle,
  onClose,
  titleId,
  descId,
}: {
  task: ParsedTask;
  featureTitle: string | undefined;
  statusStyle: StatusBadgeStyle;
  onClose: () => void;
  titleId: string;
  descId: string;
}) {
  return (
    <header className="flex items-start justify-between gap-3 border-b border-border bg-surface px-6 py-4">
      <div className="flex min-w-0 flex-col gap-2">
        <div className="flex items-center gap-2">
          <span className="bg-chip-bg px-2 py-0.5 text-xs font-semibold uppercase tracking-wide text-text-secondary">
            {task.id}
          </span>
          <span
            className={
              "px-2 py-0.5 text-xs font-semibold uppercase tracking-wide " +
              statusStyle.bg +
              " " +
              statusStyle.text
            }
          >
            {formatStatusLabel(task.status)}
          </span>
        </div>
        <h2
          id={titleId}
          className="text-xl font-semibold leading-snug text-text-primary"
        >
          {task.title || task.id}
        </h2>
        {featureTitle ? (
          <p className="text-xs text-text-muted">{featureTitle}</p>
        ) : null}
        <p id={descId} className="sr-only">
          Task detail for {task.id}: {task.title}. Status: {task.status}.
        </p>
      </div>
      <button
        type="button"
        onClick={onClose}
        aria-label="Close"
        className="shrink-0 p-1 text-text-secondary transition-colors hover:bg-surface-subtle hover:text-text-primary"
      >
        <X className="h-4 w-4" aria-hidden="true" />
      </button>
    </header>
  );
}

function MetadataSection({
  task,
  repository,
  nextAction,
  lastUpdatedAt,
}: {
  task: ParsedTask;
  repository: string | undefined;
  nextAction: string | undefined;
  lastUpdatedAt: string | undefined;
}) {
  const actorType = task.execution?.actor_type;
  const ActorIcon = actorType === "agent" ? Bot : User;
  const repositoryUrl = repository ? `https://github.com/${repository}` : null;

  return (
    <section className="grid grid-cols-2 gap-x-6 gap-y-5 pb-2">
      <MetaField
        icon={<Layers className="h-4 w-4" aria-hidden="true" />}
        label="Repository"
      >
        {repository && repositoryUrl ? (
          <a
            href={repositoryUrl}
            target="_blank"
            rel="noreferrer noopener"
            className="inline-flex items-center gap-1.5 text-primary transition-colors hover:underline"
            aria-label={`Open repository ${repository}`}
          >
            <span className="text-text-primary">{repository}</span>
            <ExternalLink className="h-3.5 w-3.5" aria-hidden="true" />
          </a>
        ) : (
          <NoneValue />
        )}
      </MetaField>

      <MetaField
        icon={<GitBranch className="h-4 w-4" aria-hidden="true" />}
        label="Branch"
      >
        {task.branch ? (
          <span className="break-all font-mono text-xs text-success">
            {task.branch}
          </span>
        ) : (
          <NoneValue />
        )}
      </MetaField>

      <MetaField
        icon={
          <ArrowRight className="h-4 w-4 text-primary" aria-hidden="true" />
        }
        label="Next Action"
      >
        {nextAction ? (
          <span className="text-text-primary">{nextAction}</span>
        ) : (
          <NoneValue />
        )}
      </MetaField>

      <MetaField
        icon={<ActorIcon className="h-4 w-4" aria-hidden="true" />}
        label="Executed By"
      >
        <div className="flex flex-col">
          <span className="capitalize text-text-primary">
            {actorType ?? "—"}
          </span>
          {lastUpdatedAt ? (
            <span className="mt-1 text-xs text-text-muted">
              {formatTimestamp(lastUpdatedAt)}
            </span>
          ) : null}
        </div>
      </MetaField>

      <MetaField label="Depends On" fullWidth>
        {task.dependsOn.length > 0 ? (
          <div className="flex flex-wrap gap-1.5">
            {task.dependsOn.map((dep) => (
              <span
                key={dep}
                className="bg-chip-bg px-2 py-0.5 text-xs font-medium text-text-secondary"
              >
                {dep}
              </span>
            ))}
          </div>
        ) : (
          <NoneValue />
        )}
      </MetaField>

      <MetaField
        icon={
          task.blockedReason ? (
            <AlertCircle className="h-4 w-4 text-danger" aria-hidden="true" />
          ) : null
        }
        label="Blocked Reason"
        fullWidth
      >
