        </div>
        <span className="text-xs text-text-muted">by {entry.by}</span>
        {entry.note ? (
          <p className="mt-1 text-sm text-text-secondary">{entry.note}</p>
        ) : null}
      </div>
    </li>
  );
}

function TimelineStatusBadge({
